# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMT2-000001",
    "name": "Murugan முருகன்",
    "kind": "first-name",
    "meaning": "Murugan (முருகன்) is a masculine given name in Tamil. Meaning: The Tamil god of war and victory.."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Mur")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

